<?php
declare(strict_types=1);
require __DIR__.'/lib/render.php';
try {$r=Norda\record((string)($_GET['id']??''));Norda\can('quote');if($r['kind']!=='quote')Norda\fail('Təklif tapılmadı.',404);$d=$r['data'];$company=Norda\published('company')[0]??Norda\seed()['company'];$number='NTS-'.strtoupper(substr($r['id'],0,8));$date=(new DateTimeImmutable($r['updated_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Baku'))->format('d.m.Y');header('Content-Type: text/html; charset=utf-8');header('Cache-Control: private,no-store');header('X-Robots-Tag: noindex,nofollow');}catch(Norda\Problem$e){http_response_code($e->status);exit(Norda\e($e->getMessage()));}
?><!doctype html><html lang="az"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?=Norda\e($number)?> — Kommersiya təklifi</title><link rel="stylesheet" href="quote.css"><script src="quote-print.js" defer></script></head><body><div class="print-tools"><button id="print">Çap / PDF saxla</button><span>Brauzerin çap pəncərəsində “PDF kimi saxla” seçin.</span></div><main class="sheet"><header><img src="../assets/norda-logo.svg" alt="Norda Tech Supplies"><div><strong><?=Norda\e($company['name'])?></strong><p><?=Norda\e($company['displayPhone']??$company['phone'])?><br><?=Norda\e($company['email'])?></p><?php if(!empty($company['tax_number'])):?><p>VÖEN: <?=Norda\e($company['tax_number'])?></p><?php endif;?></div></header><section class="title"><p>KOMMERSİYA TƏKLİFİ</p><h1><?=Norda\e($number)?></h1><span><?=$date?></span><?php if($d['status']==='draft'):?><b class="draft">QARALAMA</b><?php endif;?></section><section class="customer"><div><small>ŞİRKƏT / MÜŞTƏRİ</small><strong><?=Norda\e($d['customer'])?></strong><p><?=Norda\e($d['contact'])?></p></div><div><small>VALYUTA</small><strong><?=Norda\e($d['currency'])?></strong><?php if($d['valid_until']):?><p>Təklifin son tarixi: <?=Norda\e($d['valid_until'])?></p><?php endif;?></div></section><table><thead><tr><th>№</th><th>Məhsul / Part Number</th><th>Say</th><th>Vahid qiyməti</th><th>Məbləğ</th></tr></thead><tbody><?php foreach($d['items']as$i=>$item):?><tr><td><?=$i+1?></td><td><strong><?=Norda\e($item['name'])?></strong><small><?=Norda\e($item['part_number'])?></small></td><td><?=Norda\e($item['quantity'])?></td><td><?=number_format($item['price_cents']/100,2,'.',' ')?></td><td><?=number_format($item['line_cents']/100,2,'.',' ')?></td></tr><?php endforeach;?></tbody></table><div class="total"><span>CƏMİ</span><strong><?=number_format($d['total_cents']/100,2,'.',' ')?> <?=Norda\e($d['currency'])?></strong></div><section class="terms"><?php foreach(['delivery'=>'Çatdırılma','warranty'=>'Zəmanət','tax_note'=>'Vergi / ƏDV qeydi','terms'=>'Digər şərtlər']as$key=>$label):if(!empty($d[$key])):?><div><h2><?=$label?></h2><p><?=nl2br(Norda\e($d[$key]))?></p></div><?php endif;endforeach;?></section><footer><?=Norda\e($company['name'])?> · <?=Norda\e($company['email'])?> · nordatech.az</footer></main></body></html>
